        "path": "/vendor/priorEnforcement",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "o1-new-vendor-review",
      "onUnknown": "ignore"
    },
    {
      "id": "o2-suppress-risk-rejection",
      "description": "O2 suppresses automatic risk rejection for a clear-screened critical supplier.",
      "when": {
